class Solution {
    double radius, xc, yc;
    mt19937 gen;
    uniform_real_distribution<double> dis;
public:
    Solution(double radius, double x_center, double y_center)
        : radius(radius), xc(x_center), yc(y_center), gen(random_device{}()), dis(0.0, 1.0) {
    }

    vector<double> randPoint() {
        double u = dis(gen);
        double r = radius * sqrt(u);
        double theta = 2.0 * acos(-1.0) * dis(gen);
        return {xc + r * cos(theta), yc + r * sin(theta)};
    }
};
